# Let's see if there's a consistent logical operation

def check_transform(left_grid, right_grid):
    """Check various transforms"""
    n = len(left_grid)

    # Try XOR-like operation
    xor_error = 0
    for r in range(n):
        for c in range(10):
            l = left_grid[r][c]
            x = right_grid[r][c]
            if (l == 2 and x == 9) or (l == 7 and x == 7):
                pass  # OK (2 XORed = 9, 7 XORed = 7)
            else:
                xor_error += 1
    print(f"XOR pattern (2->9, 7->7): {n*10-xor_error} matches")

    # Try AND-like
    and_error = 0
    for r in range(n):
        for c in range(10):
            l = left_grid[r][c]
            x = right_grid[r][c]
            if (l == 7 and x == 7) or (l == 2 and x == 9):
                pass  # OK (AND: 7 and 7 = 7, 7 and 2 = 9)
            else:
                and_error += 1
    print(f"AND pattern (7&7=7, 2&7=9): {n*10-and_error} matches")

    # Try OR-like  
    or_error = 0
    for r in range(n):
        for c in range(10):
            l = left_grid[r][c]
            x = right_grid[r][c]
            if (l == 7 and x == 9) or (l == 2 and x == 7):
                pass  # OK (OR: 7 or 7 = 9, 2 or 7 = 7)
            else:
                or_error += 1
    print(f"OR pattern (7or7=9, 2or7=7): {n*10-or_error} matches")

check_transform(left_grid, right_grid)

